arguments.command:
cd /workspace && export OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 MKL_NUM_THREADS=1 LD_LIBRARY_PATH="$PWD/native" PYTHONPATH="$PWD/.deps"; python3 - <<'PY'
import sys,random,math
sys.path.insert(0,'submission');sys.path.insert(0,'tmp')
from protocol import validate
from te.session import run_case
import gen_replay_test as g
random.seed(20251113)
mx={}
def upd(k,v):
 mx[k]=max(mx.get(k,0),abs(v))
for trial in range(2000):
 ncases=random.choices([0,1,1,1,2,3],[1,4,5,5,2,1])[0]
 cases=[g.gen_case(i,trial%2) for i in range(ncases)]
 req={'cases':cases};validate(req);out={'cases':[run_case(c) for c in cases]}
 for cout in out['cases']:
  for r in cout['events']:
   if r['op']=='issue':
    for v in r['bias']:upd('bias',v)
    res=r['result']
    if res['status']=='optimal':
     for row in res['flow']:
      for v in row:upd('flow',v)
     for v in res['edge_load']:upd('edge_load',v)
     for v in res['potential']:upd('potential',v)
   elif r['op']=='step' and r['status']=='advanced':
    for k in ['load','z','dual','pressure']:
     for v in r[k]:upd(k,v)
    upd('ceiling',r['ceiling'])
   elif r['op']=='audit':
    for row in r['flow']:
     for v in row:upd('flow',v)
    for row in r['worker_load']:
     for v in row:upd('worker_load',v)
    for k in ['load','z','dual']:
     for v in r[k]:upd(k,v)
print(mx)
PY
